const IMAGE = /\.(jpe?g|png|webp|heic)$/i;
export const THUMB_PREFIX = "thumbnails/";
export const THUMB_WIDTH = 600;

/** Target thumbnail size: oriented dimensions scaled to at most maxWidth, never upscaled. */
export function planThumbnail({ width, height, orientation = 1 }, maxWidth = THUMB_WIDTH) {
  const rotated = orientation >= 5 && orientation <= 8;
  const w = rotated ? height : width;
  const h = rotated ? width : height;
  if (w <= maxWidth) return { width: w, height: h };
  return { width: maxWidth, height: Math.max(1, Math.round((h * maxWidth) / w)) };
}

export function thumbnailName(name) {
  return `${THUMB_PREFIX}${name.replace(/\.[^./]+$/, "")}.jpg`;
}

/**
 * For every image in the album, write a JPEG thumbnail and record the original's oriented
 * dimensions in its metadata. `probe(bytes)` -> { width, height, orientation }; `resize(bytes,
 * width, height)` -> JPEG bytes. One failure never stops the album.
 */
export async function generateThumbnails(store, { eventId, albumId, force = false }, { probe, resize }) {
  const prefix = `events/${eventId}/${albumId}/`;
  const summary = { created: 0, skipped: 0, failed: 0, errors: [] };
  for (const { name, metadata } of await store.list(prefix)) {
    if (!IMAGE.test(name)) continue;
    const target = thumbnailName(name);
    if (!force && (await store.exists(target))) {
      summary.skipped += 1;
      continue;
    }
    try {
      const bytes = await store.get(name);
      const original = probe(bytes);
      const size = planThumbnail(original);
      const rotated = original.orientation >= 5 && original.orientation <= 8;
      await store.put(target, resize(bytes, size.width, size.height), { width: String(size.width), height: String(size.height) });
      await store.setMetadata(name, { ...metadata,
        width: String(rotated ? original.height : original.width),
        height: String(rotated ? original.width : original.height) });
      summary.created += 1;
    } catch (error) {
      summary.failed += 1;
      summary.errors.push(`${name.slice(prefix.length)}: ${error instanceof Error ? error.message : String(error)}`);
    }
  }
  return summary;
}
